<script>
export default {
    data() {
        return {
            plagas:[
                {
                    parron: 318,
                    plagas:[
                        'Gusano de seda',
                        'Arañita roja',
                        'Espoascas'
                    ]
                },
                {
                    parron: 316,
                    plagas:[
                        'Arañita roja',
                        'Espoascas'
                    ]
                },
                {
                    parron: 315,
                    plagas:[
                        'Arañita roja',
                    ]
                },
            ]
        }
    },
    methods: {
        procesarParron(id) {
            const resultado = this.plagas.filter(item => item.parron === id);
            this.$emit('parronSeleccionado', resultado[0])
            // alert('El parrón '+resultado[0].parron+' tiene las siguientes plagas: ' + resultado[0].plagas.join(', '))
        },
        verInfoParron() {
            return '#cacaca'
        },
    }
}
</script>

